+/* Fall back to the historical INT_MAX bound if nothing has already defined
+ * a (presumably more precise) bound for a validated element-count product.
+ */
+#if !defined(MATIO_MAX_EDGE_PRODUCT)
+#define MATIO_MAX_EDGE_PRODUCT ((size_t)INT_MAX)
+#endif
+
+/** @brief Checks the product of the edge dimensions for overflow
+ *
+ * Validates that each edge is non-negative and that the product of the edge
+ * dimensions does not overflow and stays within @c MATIO_MAX_EDGE_PRODUCT, the
+ * largest element count that could plausibly be allocated.
+ * @param rank Number of dimensions
+ * @param edge Number of elements to read per dimension
+ * @retval 0 on success
+ */
+int
+CheckEdgeOverflow(int rank, const int *edge, size_t extra)
+{
+    int i, err;
+    size_t nElements = 1;
+    for ( i = 0; i < rank; i++ ) {
+        if ( edge[i] < 0 ) {
+            return MATIO_E_BAD_ARGUMENT;
+        }
+        err = Mul(&nElements, nElements, (size_t)edge[i]);
+        if ( err || nElements > MATIO_MAX_EDGE_PRODUCT ) {
+            return MATIO_E_INDEX_TOO_BIG;
+        }
+    }
+    err = Mul(&nElements, nElements, extra);
+    if ( err || nElements > MATIO_MAX_EDGE_PRODUCT ) {
+        return MATIO_E_INDEX_TOO_BIG;
+    }
+    return MATIO_E_NO_ERROR;
+}
